from datetime import date, datetime, timedelta
import sqlite3
import unittest
from unittest.mock import patch

import categories
import config
import database
import models
import friends
import training_forecast


NOW = datetime(2026, 11, 15, 10)
START = date(2026, 11, 16)
FRIDAYS = [date(2026, 10, 16), date(2026, 10, 23),
           date(2026, 10, 30), date(2026, 11, 6)]


class TrainingForecastTests(unittest.TestCase):
    """Protect true weekly evidence and make forecast generation safe to repeat."""

    def setUp(self):
        """Create an isolated database with the existing taxonomy and a synthetic archive."""
        self.connection = database.get_connection(':memory:')
        self.addCleanup(self.connection.close)
        database.init_db(self.connection)
        categories.seed_categories(self.connection, categories.load_taxonomy())
        self.import_id = self.add_import('source-one')
        self.source_rows = {}

    def add_import(self, key):
        """Add synthetic metadata without relying on any supplied personal-data file."""
        with self.connection:
            cursor = self.connection.execute('''INSERT INTO training_imports
                (file_name,source_fingerprint,imported_at) VALUES (?,?,?)''',
                (key + '.csv', key, database.to_db_text(NOW)))
        return cursor.lastrowid

    def observe(self, days, sport='Yoga', variant='Alle Level', start='12:30',
                copies=1, import_id=None):
        """Store explicit historical dates, allowing duplicate rows and repeated exports."""
        import_id = self.import_id if import_id is None else import_id
        first_id = None
        with self.connection:
            for day in days:
                for copy in range(copies):
                    source_row = self.source_rows.get(import_id, 1) + 1
                    self.source_rows[import_id] = source_row
                    cursor = self.connection.execute('''INSERT INTO training_history
                        (import_id,source_row,sport,variant,weekday_text,start_time,date_original,
                         training_date,participants_signed_up,participants_teacher,max_participants)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?)''',
                        (import_id, source_row, sport, variant,
                         config.TRAINING_WEEKDAYS_EN[day.weekday()], start, day.isoformat(),
                         day.isoformat(), 2, 3, 10))
                    if first_id is None:
                        first_id = cursor.lastrowid
        return first_id

    def scalar(self, query, params=()):
        """Read one value from fixed SQL with separate parameter values."""
        return self.connection.execute(query, params).fetchone()[0]

    def snapshot(self, table):
        """Read stable tuples using only a fixed allowlist of fixture tables."""
        statements = {
            'training_history': 'SELECT * FROM training_history ORDER BY id',
            'training_imports': 'SELECT * FROM training_imports ORDER BY id',
            'events': 'SELECT * FROM events ORDER BY id',
            'series': 'SELECT * FROM series ORDER BY id',
            'event_provenance': 'SELECT * FROM event_provenance ORDER BY event_id',
        }
        return [tuple(row) for row in self.connection.execute(statements[table]).fetchall()]

    def generate(self, start=START, now=NOW):
        """Run the public generator with explicit, reproducible planning dates."""
        return training_forecast.generate_training_forecast(self.connection, start_date=start,
                                                            now=now)

    def test_three_of_four_with_last_week_is_eligible(self):
        """Accept a weekly pattern with three distinct observations including the newest week."""
        first_id = self.observe([FRIDAYS[0], FRIDAYS[1], FRIDAYS[3]])
        result = training_forecast.derive_weekly_patterns(self.connection)
        self.assertEqual(result['anchor_date'], date(2026, 11, 6))
        self.assertEqual(len(result['patterns']), 1)
        pattern = result['patterns'][0]
        self.assertEqual(pattern['history_id'], first_id)
        self.assertEqual(pattern['weekday'], 4)
        self.assertEqual(pattern['start_time'], '12:30')
        self.assertEqual(pattern['evidence_weeks'], 3)
        self.assertEqual(pattern['first_seen'], FRIDAYS[0])
        self.assertEqual(pattern['last_seen'], FRIDAYS[3])

    def test_duplicate_rows_and_exports_do_not_inflate_evidence(self):
        """Two distinct weekly dates remain insufficient even across many duplicate exports."""
        self.observe([FRIDAYS[2], FRIDAYS[3]], copies=8)
        second = self.add_import('source-two')
        self.observe([FRIDAYS[2], FRIDAYS[3]], copies=8, import_id=second)
        result = training_forecast.derive_weekly_patterns(self.connection)
        self.assertEqual(result['patterns'], [])
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_history'), 32)

    def test_old_and_not_recently_seen_patterns_are_excluded(self):
        """Require both the rolling four-week threshold and presence in its last seven days."""
        self.observe([date(2026, 10, 9), *FRIDAYS[:3]], sport='Inactive')
        self.observe([date(2026, 9, 18), date(2026, 9, 25), date(2026, 10, 2)], sport='Old')
        self.observe([date(2026, 11, 6)], sport=None, variant=None)
        result = training_forecast.derive_weekly_patterns(self.connection)
        self.assertEqual(result['patterns'], [])

    def test_sport_variant_weekday_and_time_are_separate_patterns(self):
        """Do not merge different levels, times or weekdays to manufacture recurrence evidence."""
        self.observe(FRIDAYS[:2], sport='Tennis', variant='Level 1', start='08:00')
        self.observe(FRIDAYS[2:], sport='Tennis', variant='Level 2', start='08:00')
        self.observe(FRIDAYS[:2], sport='Tennis', variant='Level 1', start='09:00')
        self.observe([day - timedelta(days=1) for day in FRIDAYS[2:]],
                     sport='Tennis', variant='Level 1', start='08:00')
        self.assertEqual(training_forecast.derive_weekly_patterns(self.connection)['patterns'], [])

    def test_blank_sports_are_excluded_but_missing_variant_is_allowed(self):
        """Retain nameless records while projecting a named sport without a stated level."""
        self.observe(FRIDAYS, sport=None, variant='Unclassified')
        self.observe(FRIDAYS, sport='   ', variant='Unclassified')
        self.observe(FRIDAYS, sport='Pilates', variant=None)
        result = training_forecast.derive_weekly_patterns(self.connection)
        self.assertEqual(len(result['patterns']), 1)
        self.assertEqual(result['patterns'][0]['sport'], 'Pilates')
        self.assertEqual(result['patterns'][0]['variant'], '')
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_history'), 12)

    def test_pattern_identity_uses_earliest_source_row_outside_the_window(self):
        """Keep the local pattern ID stable as the evidence window advances."""
        first_id = self.observe([date(2026, 1, 2)])
        self.observe(FRIDAYS)
        pattern = training_forecast.derive_weekly_patterns(self.connection)['patterns'][0]
        self.assertEqual(pattern['history_id'], first_id)
        self.assertEqual(pattern['evidence_weeks'], 4)
        self.assertEqual(pattern['first_seen'], FRIDAYS[0])

    def test_rolling_window_includes_its_first_day_and_excludes_older_observations(self):
        """Count exactly the inclusive 28-day source window ending at the archive anchor."""
        days = [date(2026, 10, 3) + timedelta(weeks=week) for week in range(5)]
        self.observe(days)
        self.observe([date(2026, 11, 6)], sport=None, variant=None)
        pattern = training_forecast.derive_weekly_patterns(self.connection)['patterns'][0]
        self.assertEqual(pattern['evidence_weeks'], 4)
        self.assertEqual(pattern['first_seen'], date(2026, 10, 10))
        self.assertEqual(pattern['last_seen'], date(2026, 10, 31))

    def test_generation_creates_four_provisional_weeks_only(self):
        """Generate the true weekday/time with unknown availability, duration and provenance."""
        history_id = self.observe(FRIDAYS)
        report = self.generate()
        self.assertEqual(report['n_patterns'], 1)
        self.assertEqual(report['n_created'], 4)
        self.assertEqual(report['anchor_date'], '2026-11-06')
        self.assertEqual(report['first_date'], '2026-11-16')
        self.assertEqual(report['last_date'], '2026-12-13')
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM series'), 1)
        series = self.connection.execute('SELECT * FROM series').fetchone()
        self.assertEqual(series['external_id'], config.HISTORY_PATTERN_PREFIX + str(history_id))
        self.assertEqual(series['location_type'], 'tba')
        self.assertIsNone(series['price_rappen'])
        self.assertEqual(series['is_placeholder'], 0)
        rows = self.connection.execute('SELECT * FROM events ORDER BY start_time').fetchall()
        dates = [date(2026, 11, 20) + timedelta(weeks=week) for week in range(4)]
        self.assertEqual([database.from_db_text(row['start_time']).date() for row in rows], dates)
        for row in rows:
            beginning = database.from_db_text(row['start_time'])
            ending = database.from_db_text(row['end_time'])
            self.assertEqual((beginning.hour, beginning.minute), (12, 30))
            self.assertEqual(ending - beginning,
                             timedelta(minutes=config.DEFAULT_DURATION_MINUTES))
            self.assertEqual(row['status'], 'unknown')
            self.assertEqual(row['end_is_estimated'], 1)
        provenance = self.connection.execute('SELECT * FROM event_provenance').fetchall()
        self.assertEqual(len(provenance), 4)
        for row in provenance:
            self.assertEqual(row['kind'], 'projected')
            self.assertEqual(row['forecast_anchor_date'], '2026-11-06')
            self.assertEqual(row['evidence_weeks'], 4)
            self.assertIsNone(row['verification_url'])
            self.assertIsNone(row['verified_at'])

    def test_same_horizon_is_idempotent_and_preserves_archive(self):
        """A second generation leaves original rows, event IDs and creation provenance unchanged."""
        self.observe(FRIDAYS)
        original = self.snapshot('training_history')
        imports = self.snapshot('training_imports')
        self.generate()
        events, series = self.snapshot('events'), self.snapshot('series')
        provenance = self.snapshot('event_provenance')
        second = self.generate(now=NOW + timedelta(hours=1))
        self.assertEqual(second['n_created'], 0)
        self.assertEqual(second['n_existing'], 4)
        self.assertEqual(self.snapshot('events'), events)
        self.assertEqual(self.snapshot('series'), series)
        self.assertEqual(self.snapshot('event_provenance'), provenance)
        self.assertEqual(self.snapshot('training_history'), original)
        self.assertEqual(self.snapshot('training_imports'), imports)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 0)

    def test_confirmed_website_slot_is_never_downgraded(self):
        """Keep an independently verified full event and its known duration unchanged."""
        self.observe(FRIDAYS)
        self.generate()
        event_id = self.scalar('SELECT MIN(id) FROM events')
        with self.connection:
            self.connection.execute('''UPDATE events SET status='full',end_is_estimated=0,
                end_time=? WHERE id=?''', ('2026-11-20 14:30:00', event_id))
            self.connection.execute('''UPDATE event_provenance SET kind='website',
                verification_url=?,verified_at=? WHERE event_id=?''',
                ('https://example.com/verified-course', database.to_db_text(NOW), event_id))
        events, provenance = self.snapshot('events'), self.snapshot('event_provenance')
        again = self.generate()
        self.assertEqual(again['n_created'], 0)
        self.assertEqual(again['n_protected'], 1)
        self.assertEqual(self.snapshot('events'), events)
        self.assertEqual(self.snapshot('event_provenance'), provenance)

    def test_legacy_slot_without_provenance_is_not_claimed(self):
        """Do not relabel a preexisting unverified event merely because its date matches."""
        self.observe(FRIDAYS)
        self.generate()
        event_id = self.scalar('SELECT MIN(id) FROM events')
        with self.connection:
            self.connection.execute('DELETE FROM event_provenance WHERE event_id=?', (event_id,))
        before = self.snapshot('events')
        report = self.generate()
        self.assertEqual(report['n_protected'], 1)
        self.assertEqual(self.snapshot('events'), before)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM event_provenance'), 3)

    def test_known_duration_does_not_confirm_the_forecast_or_get_overwritten(self):
        """Keep a manually corrected duration separate from verification of the future date."""
        self.observe(FRIDAYS)
        self.generate()
        event_id = self.scalar('SELECT MIN(id) FROM events')
        with self.connection:
            self.connection.execute('''UPDATE events SET end_is_estimated=0,end_time=?
                WHERE id=?''', ('2026-11-20 14:30:00', event_id))
        events, provenance = self.snapshot('events'), self.snapshot('event_provenance')
        report = self.generate()
        self.assertEqual(report['n_existing'], 4)
        self.assertEqual(self.snapshot('events'), events)
        self.assertEqual(self.snapshot('event_provenance'), provenance)

    def test_generation_failure_rolls_back_all_new_series_and_events(self):
        """A provenance failure rolls back the complete new forecast, retaining the source."""
        self.observe(FRIDAYS)
        history = self.snapshot('training_history')
        with self.connection:
            self.connection.execute('''CREATE TRIGGER fail_forecast BEFORE INSERT
                ON event_provenance WHEN NEW.event_id=2
                BEGIN SELECT RAISE(ABORT, 'forced forecast test failure'); END''')
        with self.assertRaises(sqlite3.IntegrityError):
            self.generate()
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM series'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM event_provenance'), 0)
        self.assertEqual(self.snapshot('training_history'), history)
        self.assertFalse(self.connection.in_transaction)

    def test_later_horizon_adds_only_new_slots_without_deleting_previous_ones(self):
        """Reuse overlapping future dates and retain previous forecasts outside the new horizon."""
        self.observe(FRIDAYS)
        self.generate()
        before = self.snapshot('events')
        report = self.generate(date(2026, 11, 23))
        self.assertEqual(report['n_created'], 1)
        self.assertEqual(report['n_existing'], 3)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 5)
        self.assertEqual(self.snapshot('events')[:4], before)

    def test_empty_archive_rejects_and_nonrecurring_archive_creates_nothing(self):
        """Require an archive, but accept an honest lack of eligible patterns without invention."""
        with self.assertRaises(ValueError):
            training_forecast.derive_weekly_patterns(self.connection)
        self.observe([FRIDAYS[-1]])
        report = self.generate()
        self.assertEqual(report['n_patterns'], 0)
        self.assertEqual(report['n_created'], 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM series'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 0)

    def test_invalid_horizon_and_active_transaction_are_rejected(self):
        """Reject past/non-Monday dates and avoid committing a caller's unrelated writes."""
        self.observe(FRIDAYS)
        for start in [date(2026, 11, 9), date(2026, 11, 17), NOW]:
            with self.subTest(start=start), self.assertRaises(ValueError):
                self.generate(start)
        self.connection.execute('INSERT INTO app_settings (key,value) VALUES (?,?)',
                                ('pending_forecast_test', 'private'))
        with self.assertRaises(ValueError):
            self.generate()
        self.assertTrue(self.connection.in_transaction)
        self.connection.rollback()
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM series'), 0)

    def test_default_horizon_starts_next_monday(self):
        """Keep the default four-week period fully in the future for the injected clock."""
        self.observe(FRIDAYS)
        report = training_forecast.generate_training_forecast(self.connection, now=NOW)
        self.assertEqual(report['n_created'], 4)
        first = database.from_db_text(self.scalar('SELECT MIN(start_time) FROM events'))
        self.assertEqual(first.date(), date(2026, 11, 20))

    def test_unknown_availability_cannot_be_confirmed_as_bookable(self):
        """Retain unknown as a valid model state while preventing normal confirmation."""
        self.observe(FRIDAYS)
        self.generate()
        event_id = self.scalar('SELECT MIN(id) FROM events')
        with self.connection:
            self.connection.execute('''INSERT INTO users
                (id,display_name,friend_code,is_synthetic,created_at) VALUES (?,?,?,?,?)''',
                (1, 'Test user', 'TEST01', 0, database.to_db_text(NOW)))
        event = models.event_from_row(database.get_event_row(self.connection, event_id))
        self.assertEqual(event.status, 'unknown')
        self.assertIn('Availability unverified', event.display_tags())
        with self.assertRaises(ValueError):
            database.save_interaction(self.connection, 1, event_id, 'confirm', now=NOW)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 0)

        with self.assertRaisesRegex(ValueError, 'not been verified'):
            friends.send_invitations(self.connection, 1, event_id, [2], now=NOW)

    def test_active_source_limit_rejects_before_writing(self):
        """Keep an oversized forecast from leaving a partial course or dated plan."""
        self.observe(FRIDAYS)
        with patch.object(config, 'MAX_RECORDS_PER_SOURCE', 3):
            with self.assertRaises(ValueError):
                self.generate()
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM series'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_history'), 4)
